style.css:
@-moz-document domain("hlamer.ru"), domain("zseek.ru"), domain("krasview.ru") {
.wrapper {
        height: 100% !important;
    }

    /* Растягиваем основную область страницы */
    #align {
        width: 100% !important;
        max-width: none !important;
        box-sizing: border-box !important;
    }

    table.main {
        width: 100% !important;
        max-width: none !important;
    }

    #content-table,
    #content-table > tbody,
    #content-table > tbody > tr,
    #content-table td.left {
        width: 100% !important;
        max-width: none !important;
    }

    /* Убираем боковую колонку */
    #content-table td.right {
        display: none !important;
    }

    #video-side {
        display: none !important;
    }

    /* Сам видеоблок */
    .vc,
    .vc-wide,
    #video-container {
        width: 100% !important;
        max-width: none !important;
        float: none !important;
    }

    /* Плеер */
    #html5-container,
    #html5-container .mejs-container,
    #html5-container #mep_0,
    #html5-container .mejs-inner,
    #html5-container .mejs-mediaelement,
    #video-flash {
        width: 100% !important;
        max-width: none !important;
    }

    #html5-container {
        height: auto !important;
        aspect-ratio: 16 / 9 !important;
    }

    #mep_0,
    .mejs-mediaelement,
    #video-flash {
        width: 100% !important;
        height: 100% !important;
    }

    /* Убираем рекламу */
    .video-block-top-ad {
        display: none !important;
    }

    /* Комментарии */
    #video-comments,
    #video-comments .block,
    #video-comments .block-content {
        width: 99% !important;
        max-width: none !important;
    }

    /* Навигация */
    #navigation {
        width: 100% !important;
        max-width: none !important;
    }

    /* Убираем фиксированные ограничения из media-query */
    .vfc-wide {
        width: 100% !important;
        max-width: none !important;
        height: auto !important;
    }
}
